import { mergeExtend } from '@tech/t-core/RuntimeApp/build.RuntimeApp.umd.js'
import commonConfig from './common/index.js'
import config from './config/config.json'

// 参数组件名不能删除
export const name = 'base-interface'

export const getParams = () => {
  // 本地公共扩展 与 本地个性化扩展 合并
  let distOptions = mergeExtend(commonConfig)
  distOptions.global = config?.global || undefined // 赋值子配置
  return distOptions
}
