if (!window.Tech) {
  window.Tech = {}
}
window.Tech.setInterfaceAppName = (service, app) => {
  const services = ['loadMenu', 'loadView', 'profile', 'logout']
  if (app == 'base' && services.includes(service)) {
    app = 'sie-iidp-iam'
  }
  return app
}
// // window.moment = moment
let _fn = (config) => {
  // 若是装了权限app，接口入参app需改成sie-iidp-iam
  const services = ['loadMenu', 'loadView', 'profile', 'logout']
  if (
    (config?.url?.indexOf('/root/rpc/login') > -1 ||
      services.includes(config?.data?.params?.service)) &&
    config?.data?.params?.app == 'base'
  ) {
    config.data.params.app = 'sie-iidp-iam'
  }
  // 登录接口MD5加密
  if (config?.url?.indexOf('/root/rpc/login') > -1) {
    const password =
      tech_app.page.getNode('inp_meta_login_pwd').$ds.form.password
    config.data.params.password = window.Tech.utils.md5(password)
  }
  return config
}
if (!window.Tech.globalApiReq) {
  window.Tech.globalApiReq = _fn
} else {
  if (!window.__iam_app_reset_global_api_req) {
    window.__iam_app_reset_global_api_req = true
    let srcFn = window.Tech.globalApiReq
    window.Tech.globalApiReq = (config) => {
      config = _fn(config)
      config = srcFn(config) // 调回原来的
      return config
    }
  }
}
